  /** Changes the given values of a Product, read at `version`. */
  async updateProduct(id: number, data: ProductUpdate, version: number): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Product', 'was changed by someone else since it was read', ['version'])
      await this.check(uow, values, current)
      Object.assign(current, values)
      current.version = version + 1
      const updated = await uow.products.update(current)
      return ProductService.read(updated)
    })
  }

  /** Marks a Product as deleted (deleted_at); reads leave it out from then on. */
  async deleteProduct(id: number, version: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Product', 'was changed by someone else since it was read', ['version'])
      if ((await uow.orderLines.listByProductId(current.id)).length > 0) throw new ConflictError('Product', 'rows of order_lines still point to it', ['order_lines'])
      current.deletedAt = new Date()
      await uow.products.update(current)
    })
  }

  /** The products with this category_id. */
  async listProductsByCategoryId(categoryId: number): Promise<ProductRead[]> {
    return (await this.uow.products.listByCategoryId(categoryId)).map((entity) => ProductService.read(entity))
  }

  /** Links a Product and a Tag (product_tags). */
  async addTag(productId: number, tagId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, productId)
      if ((await uow.tags.findById(tagId)) === null) throw new NotFoundError('Tag', tagId)
      if (await uow.productTags.findByProductIdAndTagId(productId, tagId) !== null) throw new ConflictError('Product', 'is already linked to this Tag', ['tagId'])
      await uow.productTags.insert(Object.assign(new ProductTag(), { productId, tagId }))
    })
  }

  /** Removes the link between a Product and a Tag (product_tags). */
  async removeTag(productId: number, tagId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const link = await uow.productTags.findByProductIdAndTagId(productId, tagId)
      if (link === null) throw new NotFoundError('ProductTag', [productId, tagId])
      await uow.productTags.delete(link)
    })
  }
}

