/** Operations on tags: what each one checks before it writes. */
import type { TagCreate, TagRead, TagUpdate } from '../dtos/tag.js'
import { ProductTag } from '../entities/product-tag.js'
import { Tag } from '../entities/tag.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['label'])

/** Operations on tags. It never commits: the caller owns the transaction. */
export class TagService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "tags" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Tag | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Tag' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.label
      if (value == null) {
        if (creating || 'label' in values) errors.push({ field: 'label', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 30) errors.push({ field: 'label', message: 'is longer than 30 characters' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Tag', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Tag | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Tag with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Tag> {
    const entity = await uow.tags.findById(id)
    if (entity === null) throw new NotFoundError('Tag', id)
    return entity
  }

  /** The Tag as services return it. */
  private static read(entity: Tag): TagRead {
    return { id: entity.id, label: entity.label }
  }

  /** Stores a new Tag after checking it. */
  async createTag(data: TagCreate): Promise<TagRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.tags.insert(Object.assign(new Tag(), values))
      return TagService.read(created)
    })
  }

  /** The Tag with this key; NotFoundError when there is none. */
  async getTag(id: number): Promise<TagRead> {
    return TagService.read(await this.find(this.uow, id))
  }

  /** Every Tag, by primary key. */
  async listTags(): Promise<TagRead[]> {
    return (await this.uow.tags.list()).map((entity) => TagService.read(entity))
  }

  /** Changes the given values of a Tag. */
  async updateTag(id: number, data: TagUpdate): Promise<TagRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.tags.update(current)
      return TagService.read(updated)
    })
  }

  /** Deletes a Tag. */
  async deleteTag(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.tags.delete(current)
    })
  }

  /** Links a Tag and a Product (product_tags). */
  async addProduct(tagId: number, productId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, tagId)
      if ((await uow.products.findById(productId)) === null) throw new NotFoundError('Product', productId)
      if (await uow.productTags.findByProductIdAndTagId(productId, tagId) !== null) throw new ConflictError('Tag', 'is already linked to this Product', ['productId'])
      await uow.productTags.insert(Object.assign(new ProductTag(), { tagId, productId }))
    })
  }

  /** Removes the link between a Tag and a Product (product_tags). */
  async removeProduct(tagId: number, productId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const link = await uow.productTags.findByProductIdAndTagId(productId, tagId)
      if (link === null) throw new NotFoundError('ProductTag', [productId, tagId])
      await uow.productTags.delete(link)
    })
  }
}

